pub fn solve(n: i8) -> i8 {
    // Compute remainders at each step of the canonical decomposition.
    let rem100 = n % 100;
    let rem20 = rem100 % 20;
    let rem10 = rem20 % 10;
    let rem5  = rem10 % 5;

    // Sum the quotients for each denomination and the leftover ones.
    (n / 100)     // number of 100-value notes
    + (rem100 / 20)  // number of 20-value notes
    + (rem20 / 10)   // number of 10-value notes
    + (rem10 / 5)    // number of 5-value coins
    + rem5           // number of 1-value coins
}

